UPDATE runs SET status = CASE WHEN status IN ('queued','provisioning','running','waiting_for_approval')
  THEN 'cancelling' ELSE status END, updated_at = now()
WHERE organization_id = #{organizationId} AND id = #{id}

mapper.insert:
INSERT INTO worker_run_tokens (token_hash, organization_id, run_id, generation, lease_id, expires_at)
SELECT #{tokenHash}, l.organization_id, l.run_id, l.generation, l.lease_id, #{expiresAt}
FROM run_leases l
WHERE l.organization_id = #{organizationId} AND l.run_id = #{runId} AND l.generation = #{generation}
  AND l.lease_id = #{leaseId} AND l.status = 'leased' AND l.lease_expires_at > now()

mapper.update:
UPDATE worker_run_tokens SET revoked_at = now()
WHERE organization_id = #{organizationId} AND run_id = #{runId} AND generation = #{generation}
  AND lease_id = #{leaseId} AND revoked_at IS NULL

UPDATE idempotency_keys SET response_status = #{status},
  response_body = #{body, typeHandler=com.kross.support.JsonbTypeHandler}, resource_id = #{resourceId}
WHERE organization_id = #{organizationId} AND scope = #{scope} AND idempotency_key = #{key}
  AND request_hash = #{hash} AND response_body IS NULL

mapper.delete:
DELETE FROM idempotency_keys
WHERE organization_id = #{organizationId} AND scope = #{scope} AND idempotency_key = #{key}
  AND request_hash = #{hash} AND response_body IS NULL

mapper.update:
UPDATE runs SET checkpoint_key = #{checkpointKey}, updated_at = now()
WHERE organization_id = #{organizationId} AND id = #{runId}
  AND status IN ('running','waiting_for_approval')

UPDATE approvals SET status = #{status}, decided_by = #{decidedBy}, decision_reason = #{decisionReason},
  decided_at = now(), decision_idempotency_key = #{decisionIdempotencyKey}
WHERE organization_id = #{organizationId} AND id = #{id} AND status = 'pending'

