INSERT INTO run_events
  (public_event_id, organization_id, project_id, task_id, run_id, generation, seq, type, occurred_at, payload)
SELECT #{publicEventId}, #{organizationId}, #{projectId}, #{taskId}, #{runId},
  COALESCE(MAX(generation), 1), COALESCE(MAX(seq), 0) + 1, 'approval.decided', now(),
  #{payload, typeHandler=com.kross.support.JsonbTypeHandler}
FROM run_events WHERE run_id = #{runId}
